"""Write docs/api.md from the OpenAPI schema (docs/openapi.yaml, generated by drf-spectacular).

    cd server && .venv/bin/python manage.py spectacular --file ../docs/openapi.yaml --validate
    .venv/bin/python ../scripts/api_reference.py          # rewrites ../docs/api.md

The endpoints are grouped by their first path segment after /api/v1/; each line shows the methods and the first line
of the view's description (or its summary).
"""
from __future__ import annotations

import sys
from collections import defaultdict
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
SCHEMA = ROOT / 'docs' / 'openapi.yaml'
OUT = ROOT / 'docs' / 'api.md'
METHODS = ('get', 'post', 'put', 'patch', 'delete')

HEADER = """# API reference

Hajiri's backend is a Django REST API under `/api/v1/`; the web app is the React app in `frontend/` (plain
JavaScript), which Django serves as its committed build. The endpoints keep the paths, methods, query parameters,
request bodies, JSON field names, status codes and error JSON of the TypeScript API the React app was written against
(git history, commit `65a9079`: `apps/api/src/modules/<module>/routes.ts`). They are Django REST framework views with
the project's authentication (the `hajiri_session` cookie, checked for the same origin, or `Authorization: Bearer
<token>` from `POST /api/v1/auth/login`), permission and error classes. Errors are `{"error": "<message>"}`, with
`details` or `issues` (`[{path, message}]`) where the TS API sent them.

- **Live, browsable reference:** `/api/docs` on a running install (Swagger UI, signed in as an admin), schema at
  `/api/schema`.
- **Schema file:** [`docs/openapi.yaml`](openapi.yaml), OpenAPI 3 generated by drf-spectacular. Regenerate it and
  this page after changing an endpoint:

  ```sh
  cd server && .venv/bin/python manage.py spectacular --file ../docs/openapi.yaml --validate
  .venv/bin/python ../scripts/api_reference.py
  ```

- **Every call of the web app has an endpoint:** `server/tests/web/test_frontend_api_paths.py` reads `frontend/src`
  and resolves each API path and method in Django.
- **Device gateway** (port 8080: ZKTeco ADMS `/iclock/*`, Hikvision `/hikvision/event`, `/health`, `/public-key`):
  see [`gateway.md`](gateway.md). Print the full URL map with `server/.venv/bin/python scripts/django_routes.py --all`.
"""


def first_line(op: dict) -> str:
    text = (op.get('description') or op.get('summary') or '').strip()
    return text.splitlines()[0].replace('|', '\\|') if text else ''


def render(schema: dict) -> str:
    groups: dict[str, list[str]] = defaultdict(list)
    paths = schema.get('paths', {})
    for path in sorted(paths):
        ops = paths[path]
        methods = [m for m in METHODS if m in ops]
        if not methods:
            continue
        rest = path.removeprefix('/api/v1/') if path.startswith('/api/v1/') else path.lstrip('/')
        group = rest.split('/')[0] or 'other'
        what = next((first_line(ops[m]) for m in methods if first_line(ops[m])), '')
        groups[group].append(f"| `{path}` | {' '.join(m.upper() for m in methods)} | {what} |")
    count = sum(len(v) for v in groups.values())
    out = [HEADER, f'## Endpoints in the schema ({count} paths)\n',
           "The first line of each endpoint's description; the schema file has parameters, request bodies and "
           'responses.\n']
    for group in sorted(groups):
        out += [f'### {group}\n', '| Path | Methods | What |', '|---|---|---|', *groups[group], '']
    return '\n'.join(out)


if __name__ == '__main__':
    schema = yaml.safe_load(SCHEMA.read_text())
    OUT.write_text(render(schema))
    sys.stdout.write(f'{OUT.relative_to(ROOT)}: {sum(1 for _ in OUT.open())} lines\n')
